package io.github.astelev.around_planet.client;
import io.github.astelev.around_planet.space.*;
import io.github.astelev.around_planet.network.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;
import java.util.concurrent.*;
/** Pure predictions run off the render thread; one in-flight calculation, no unbounded work queue. */
final class RendezvousMapLayer {
    private static final ExecutorService WORKER=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"around-planet-rendezvous-map");t.setDaemon(true);return t;});
    private final OrbitMapScreen map;private Button choose,clear;private SpaceTrajectory own,target;private ManeuverPreview preview;private SpaceMapPayload.Body body;private OrbitPlot targetPlot;private ManeuverPreview targetCurve;private List<OrbitInspection.Apsis> targetApsides=List.of();private RendezvousMath.Planes planes,plannedPlanes;private RendezvousMath.Prediction prediction;private CompletableFuture<RendezvousMath.Prediction> job;private UUID jobTarget;private long calculated=Long.MIN_VALUE;private int planHash,jobHash,predictionHash;private ManeuverPayload lastPacket;private RendezvousPayload lastState;private long refreshed=Long.MIN_VALUE;private UUID displayed;private double radius,entry;
    RendezvousMapLayer(OrbitMapScreen map){this.map=map;}
    Button init(int x,int y,int w){choose=Button.builder(Component.translatable("around_planet.rendezvous.off"),b->cycle()).bounds(x,y,w-22,18).build();clear=Button.builder(Component.literal("×"),b->clear()).bounds(x+w-18,y,18,18).build();clear.setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.translatable("around_planet.rendezvous.clear")));return choose;}
    Button clearButton(){return clear;}
    private void clear(){var packet=ManeuverClient.current();if(packet!=null&&!packet.session().equals(ManeuverPayload.NONE))PacketDistributor.sendToServer(new ManeuverPayload.Target(packet.session(),ManeuverPayload.NONE));}
    private void cycle(){var packet=ManeuverClient.current();var catalog=SpaceMapCatalog.current();if(packet==null||packet.session().equals(ManeuverPayload.NONE)||catalog==null)return;var ids=catalog.bodies().stream().map(SpaceMapPayload.Body::id).toList();var current=RendezvousClient.current();int i=current==null?-1:ids.indexOf(current.target());var selected=i+1>=ids.size()?ManeuverPayload.NONE:ids.get(i+1);PacketDistributor.sendToServer(new ManeuverPayload.Target(packet.session(),selected));}
    boolean select(double x,double y){var packet=ManeuverClient.current();var cat=SpaceMapCatalog.current();if(packet==null||packet.session().equals(ManeuverPayload.NONE)||cat==null)return false;var hit=pointAt(x,y);if(hit!=null&&hit.tick()>ManeuverClient.now())return map.planAt(hit.tick());for(var b:cat.bodies()){var p=new SpaceVector(b.x(),b.y(),b.z());var point=map.project(p);if(Math.hypot(point.x()-x,point.y()-y)<10&&map.visible(p)){PacketDistributor.sendToServer(new ManeuverPayload.Target(packet.session(),b.id()));return true;}}return false;}
    boolean active(){return RendezvousClient.active()&&target!=null;}
    void update(double radius,double entry){this.radius=radius;this.entry=entry;var state=RendezvousClient.current();var catalog=SpaceMapCatalog.current();var packet=ManeuverClient.current();if(clear!=null)clear.active=packet!=null&&!packet.session().equals(ManeuverPayload.NONE)&&state!=null&&state.active();if(choose!=null){choose.active=packet!=null&&!packet.session().equals(ManeuverPayload.NONE)&&catalog!=null;String name=state!=null&&state.active()?state.name():"";choose.setMessage(Component.translatable(name.isEmpty()?"around_planet.rendezvous.off":"around_planet.rendezvous.target",name.length()>16?name.substring(0,15)+"…":name));choose.setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.translatable("around_planet.rendezvous.choose")));}if(state==null||!state.active()||packet==null){target=null;prediction=null;return;}
        if(!state.target().equals(displayed)){displayed=state.target();prediction=null;calculated=Long.MIN_VALUE;}
        if(job!=null&&job.isDone()){try{var result=job.join();if(state.target().equals(jobTarget)&&packet.nodes().hashCode()==jobHash){prediction=result;predictionHash=jobHash;}else prediction=null;}catch(CompletionException ignored){prediction=null;}job=null;}
        if(prediction!=null&&predictionHash!=packet.nodes().hashCode())prediction=null;
        if(packet==lastPacket&&state==lastState&&ManeuverClient.now()-refreshed<5)return;lastPacket=packet;lastState=state;refreshed=ManeuverClient.now();
        target=new SpaceTrajectory("target",state.now(),state.other(),state.mu());own=packet.trajectory();preview=ManeuverPreview.create(own,ManeuverClient.now(),packet.nodes(),radius,entry);targetCurve=ManeuverPreview.create(target,ManeuverClient.now(),List.of(),radius,entry);targetApsides=OrbitInspection.apsides(target,ManeuverClient.now(),radius,entry,false);targetPlot=OrbitPlot.create(target.at(ManeuverClient.now()),target.mu(),radius,entry,false);planes=RendezvousMath.planes(own.at(ManeuverClient.now()),target.at(ManeuverClient.now()),own.mu());plannedPlanes=null;if(!preview.nodes().isEmpty()){var last=preview.nodes().getLast();plannedPlanes=RendezvousMath.planes(last.after().initial(),target.at(last.node().tick()),own.mu());}

        if(job==null&&(calculated==Long.MIN_VALUE||ManeuverClient.now()-calculated>=40||packet.nodes().hashCode()!=planHash||!state.target().equals(jobTarget))){calculated=ManeuverClient.now();planHash=packet.nodes().hashCode();jobHash=planHash;jobTarget=state.target();var a=own;var b=target;var plan=preview;long now=calculated;job=CompletableFuture.supplyAsync(()->RendezvousMath.predict(a,plan,b,now,radius,entry),WORKER);}
    }
    boolean isTarget(UUID id){return active()&&RendezvousClient.current().target().equals(id);}
    void paths(GuiGraphics g,boolean behind){if(!active())return;for(int i=1;i<targetPlot.points().size();i++){var a=map.project(targetPlot.points().get(i-1));var b=map.project(targetPlot.points().get(i));if(((a.depth()+b.depth())/2<0)==behind)map.line(g,a.x(),a.y(),b.x(),b.y(),behind?0xff675080:0xffbd97ff);}}
    void markers(GuiGraphics g){if(!active())return;if(prediction!=null){int i=0;for(var a:prediction.approaches()){if(a.tick()<ManeuverClient.now())continue;if(++i>3)break;var x=map.project(a.own().position());var y=map.project(a.target().position());if(map.visible(a.own().position())&&map.visible(a.target().position()))map.line(g,x.x(),x.y(),y.x(),y.y(),0xff607b8b);String distance=a.distance()<1000?String.format(Locale.ROOT,"%.0f m",a.distance()):String.format(Locale.ROOT,"%.1f km",a.distance()/1000);map.marker(g,a.own().position(),0xffffda79,String.format(Locale.ROOT,"CA%d · %s · %.1f m/s",i,distance,a.speed()));map.marker(g,a.target().position(),0xffbd97ff,"T"+i);}}var p=target.at(ManeuverClient.now()).position();map.marker(g,p,0xffbd97ff,"◎ "+RendezvousClient.current().name());for(var a:targetApsides)map.marker(g,a.position(),0xffbd97ff,a.apo()?"T Ap":"T Pe");if(planes!=null){map.marker(g,planes.ascending(),0xff8ed6fa,"AN");map.marker(g,planes.descending(),0xff8ed6fa,"DN");}if(plannedPlanes!=null){map.marker(g,plannedPlanes.ascending(),0xffffac4d,"Δv AN");map.marker(g,plannedPlanes.descending(),0xffffac4d,"Δv DN");}}

    void panel(GuiGraphics g,int left,int top,int right,int bottom){if(!active())return;g.enableScissor(left,top,right,bottom);var font=map.getMinecraft().font;int x=left+5,y=top+5;var lines=new ArrayList<Component>();lines.add(Component.translatable("around_planet.rendezvous.target",RendezvousClient.current().name()));lines.add(Component.literal("Pe: "+alt(targetPlot.periapsis())+"   Ap: "+(targetPlot.open()?"∞":alt(targetPlot.apoapsis()))));var t=target.at(ManeuverClient.now());var h=t.position().cross(t.velocity());if(h.length()>1e-8){double inc=Math.toDegrees(Math.acos(Math.clamp(h.z()/h.length(),-1,1)));var n=new SpaceVector(0,0,1).cross(h);String lan=n.length()<1e-8?"—":String.format(Locale.ROOT,"%.2f°",(Math.toDegrees(Math.atan2(n.y(),n.x()))+360)%360);lines.add(Component.literal(String.format(Locale.ROOT,"T %.0fs · i %.1f° · Ω %s",targetPlot.period(),inc,lan)));}if(planes!=null)lines.add(Component.translatable("around_planet.rendezvous.inclination",number(planes.inclination())));if(plannedPlanes!=null)lines.add(Component.translatable("around_planet.rendezvous.planned_inclination",number(plannedPlanes.inclination())));int width=Math.min(right-left-12,lines.stream().mapToInt(font::width).max().orElse(120)+8);g.fill(x-3,y-3,x+width,y+lines.size()*11,0xd9071422);for(int i=0;i<lines.size();i++){int color=i<3?0xffbd97ff:i==3&&planes!=null?0xff8ed6fa:0xffffac4d;g.drawString(font,lines.get(i),x,y,color,false);y+=11;}double distance=RendezvousClient.other().position().subtract(RendezvousClient.own().position()).length(),speed=RendezvousClient.other().velocity().subtract(RendezvousClient.own().velocity()).length();for(var text:List.of(Component.translatable("around_planet.rendezvous.distance",String.format(Locale.ROOT,"%.1f",distance)),Component.translatable("around_planet.rendezvous.speed",String.format(Locale.ROOT,"%.2f",speed)))){g.drawString(font,text,right-font.width(text)-5,bottom-25,0xffbd97ff,false);bottom+=11;}g.disableScissor();}
    private record Point(SpaceVector position,long tick,SpaceState state,String name,boolean planned,double angle,RendezvousMath.Approach approach){}
    private List<Point> points(){
        if(!active())return List.of();var list=new ArrayList<Point>();
        for(var a:targetApsides)list.add(new Point(a.position(),a.tick(),a.path().at(a.tick()),a.apo()?"target_apoapsis":"target_periapsis",false,Double.NaN,null));
        planePoints(list,planes,own,ManeuverClient.now(),false);
        if(plannedPlanes!=null&&!preview.nodes().isEmpty()){var n=preview.nodes().getLast();planePoints(list,plannedPlanes,n.after(),n.node().tick(),true);}
        if(prediction!=null){int count=0;for(var a:prediction.approaches()){if(a.tick()<ManeuverClient.now())continue;if(++count>3)break;boolean planned=preview.nodes().stream().anyMatch(n->n.node().tick()<=a.tick());list.add(new Point(a.own().position(),a.tick(),a.own(),"closest_own",planned,Double.NaN,a));list.add(new Point(a.target().position(),a.tick(),a.target(),"closest_target",planned,Double.NaN,a));}}
        return list;
    }
    private void planePoints(List<Point> list,RendezvousMath.Planes nodes,SpaceTrajectory path,long from,boolean planned){
        if(nodes==null)return;var ellipse=EllipticArc.of(path.at(from),path.mu());
        for(boolean ascending:new boolean[]{true,false}){var position=ascending?nodes.ascending():nodes.descending();if(position==null)continue;long tick=ellipse==null?-1:ManeuverPreview.tickAt(from,ellipse.secondsTo(position));
            list.add(new Point(position,tick,tick<0?null:path.at(tick),(planned?"planned_":"")+(ascending?"ascending_node":"descending_node"),planned,nodes.inclination(),null));}
    }
    private Point pointAt(double mx,double my){Point picked=null;double best=10;for(var point:points()){var p=map.project(point.position());double d=Math.hypot(p.x()-mx,p.y()-my);if(d<=10&&map.visible(point.position())&&(picked==null||point.planned()&&!picked.planned()||point.planned()==picked.planned()&&d<=best)){picked=point;best=d;}}return picked;}
    boolean tooltip(GuiGraphics g,int mx,int my){
        if(!active())return false;var lines=new ArrayList<Component>();var hit=pointAt(mx,my);
        if(hit!=null){
            lines.add(Component.translatable("around_planet.map."+hit.name()));
            if(hit.tick()>=0)lines.add(Component.translatable("around_planet.map.point_time",number(Math.max(0,(hit.tick()-ManeuverClient.now())/20.0))));
            if(hit.state()!=null)lines.add(Component.translatable("around_planet.map.point_speed",number(hit.state().velocity().length())));
            lines.add(Component.translatable("around_planet.map.point_altitude",number(hit.position().length()-radius)));
            if(Double.isFinite(hit.angle()))lines.add(Component.translatable("around_planet.rendezvous.inclination",number(hit.angle())));
            if(hit.approach()!=null){lines.add(Component.translatable("around_planet.rendezvous.distance",number(hit.approach().distance())));lines.add(Component.translatable("around_planet.rendezvous.speed",number(hit.approach().speed())));}
            var p=map.project(hit.position());g.fill((int)p.x()-3,(int)p.y()-3,(int)p.x()+4,(int)p.y()+4,0xffffff99);
        }
        if(lines.isEmpty()&&mx>=13&&mx<Math.min(map.width-195,220)&&my>=37&&my<49){lines.add(Component.translatable("around_planet.rendezvous.target",RendezvousClient.current().name()));if(prediction!=null)lines.add(Component.translatable("around_planet.rendezvous.horizon",number(Math.max(0,(prediction.until()-ManeuverClient.now())/20.0))));}
        if(lines.isEmpty()){long tick=targetTick(mx,my);if(tick>=0){var state=target.at(tick);lines.add(Component.translatable("around_planet.rendezvous.target",RendezvousClient.current().name()));lines.add(Component.translatable("around_planet.map.point_time",number(Math.max(0,(tick-ManeuverClient.now())/20.0))));lines.add(Component.translatable("around_planet.map.point_speed",number(state.velocity().length())));lines.add(Component.translatable("around_planet.map.point_altitude",number(state.position().length()-radius)));}}
        if(lines.isEmpty())return false;g.renderComponentTooltip(map.getMinecraft().font,lines,mx,my);return true;
    }
    private long targetTick(double mx,double my){for(var a:targetApsides){var xy=map.project(a.position());if(Math.hypot(xy.x()-mx,xy.y()-my)<=10&&map.visible(a.position()))return a.tick();}double best=8;long low=-1,high=-1;for(var seg:targetCurve.segments())for(int i=1;i<seg.points().size();i++){var a=seg.points().get(i-1);var b=seg.points().get(i);var x=map.project(a.position());var y=map.project(b.position());double dx=y.x()-x.x(),dy=y.y()-x.y(),d=dx*dx+dy*dy;if(d<1e-8)continue;double t=Math.clamp(((mx-x.x())*dx+(my-x.y())*dy)/d,0,1),distance=Math.hypot(x.x()+t*dx-mx,x.y()+t*dy-my);if(distance<best&&map.visible(a.position().add(b.position().subtract(a.position()).scale(t)))){best=distance;low=a.tick();high=b.tick();}}if(low<0)return -1;for(int i=0;i<28&&high-low>2;i++){long a=low+(high-low)/3,b=high-(high-low)/3;var x=map.project(target.at(a).position());var y=map.project(target.at(b).position());if(Math.hypot(x.x()-mx,x.y()-my)<Math.hypot(y.x()-mx,y.y()-my))high=b;else low=a;}return low+(high-low)/2;}
    private String alt(SpaceVector p){return p==null?"—":String.format(Locale.ROOT,"%.0f m",p.length()-radius);}
    private static String number(double v){return Double.isFinite(v)?String.format(Locale.ROOT,"%.2f",v):"—";}
}
